import asyncio

async def act(page):
    # Locate the price textbox using the accessibility tree
    price_group = page.get_by_role("group").filter(has=page.get_by_role("textbox", name="[GLOBAL] Price * $"))
    price_textbox = price_group.get_by_role("textbox", name="[GLOBAL] Price * $")

    # Get the current price value
    current_price_str = await price_textbox.input_value()
    # Convert to float for calculation
    try:
        current_price = float(current_price_str)
    except ValueError:
        # If conversion fails, assume it's a string with currency symbol and extract numeric part
        # Remove non-numeric characters except decimal point
        import re
        numeric_str = re.sub(r'[^\d.]', '', current_price_str)
        current_price = float(numeric_str) if numeric_str else 0.0

    # Calculate new price (reduce by 15%)
    new_price = current_price * 0.85
    # Format to two decimal places as typical for currency
    new_price_str = f"{new_price:.2f}"

    # Set the new price
    await price_textbox.fill(new_price_str)

    # Save the changes
    save_button = page.get_by_role("button", name="Save")
    await save_button.click()

    # Wait for potential page load after save
    await asyncio.sleep(3)

    # Return the new price as the result
    return new_price_str
